async function processLineByLine() {
    try {
    // Cria uma interface de leitura de linha a linha para o arquivo no caminho especificado
    // @ts-ignore
    const rl = readline.createInterface({
        input: fs.createReadStream(path),
        crlfDelay: Infinity
    });
    // Loop através de cada linha do arquivo
    for await (const line of rl) {
        msg.payload = JSON.parse(line);  // Define a propriedade 'payload' do objeto 'msg' como a linha atual
        msg.path = path;
        node.send(msg);  // Envia o objeto 'msg' com a linha atual para a próxima etapa do fluxo
        node.done();  // Indica que o nó terminou de processar a entrada atual
        break;  // Para o loop depois de processar a primeira linha
    }
    // Fecha a interface de leitura de linha a linha e o stream de arquivo
    rl.close();
    fs.createReadStream(path).close();
    } catch {
        node.warn("Nao foi possivel");
    }
}

