// Função para verificar a validade do payload
function isValidPayload(payload) {
    return (
        typeof payload.state === 'number' &&
        typeof payload.strstate === 'string' &&
        typeof payload.duration === 'number' &&
        !isNaN(parseFloat(payload.duration)) // Verifica se a duração é um número válido
    );
}


// Função para iniciar um novo estado
function start_state(istate) {
    let actual_state = {
        state: istate,
        inicio: new Date(),
        duration: 0.0
    };
    flow.set("actual_state", actual_state);
    node.warn(`Novo estado iniciado: ${istate}`);
}

// Função para atualizar o estado atual
function atualiza_state() {
    let actual_state = flow.get("actual_state") || {
        state: 0,
        inicio: new Date(),
        duration: 0
    };
    let agora = new Date();
    // @ts-ignore
    actual_state.duration = (agora - actual_state.inicio) / 60000; // Duração em minutos
    flow.set("actual_state", actual_state);
    node.warn(`Estado atualizado: ${actual_state.state} com duração de ${actual_state.duration.toFixed(2)} minutos`);
}

// Função para registrar o estado anterior
function registra_state(istate, strstate) {
    let last_state = flow.get("actual_state") || {
        state: 0,
        strstate: "",
        inicio: new Date(),
        final: new Date(),
        duration: 0
    };
    last_state.state = istate;
    last_state.strstate = strstate;
    last_state.final = new Date();
    last_state.duration = Number((last_state.final - last_state.inicio) / 60000); // Duração em minutos
    flow.set("last_state", last_state);
    node.warn(`Estado registrado: ${last_state.state} com duração de ${last_state.duration} minutos`);
}

