// Função para simular o estado com base nas probabilidades
function simulateState(probabilities) {
    // Verificar se a soma das probabilidades é aproximadamente igual a 1
    const totalProbability = probabilities.reduce((acc, prob) => acc + prob, 0);
    const epsilon = 0.000001; // margem de erro para comparação de ponto flutuante
    if (Math.abs(totalProbability - 1) > epsilon) {
        throw new Error('A soma das probabilidades deve ser aproximadamente igual a 1.');
    }
    // Gerar um número aleatório entre 0 e 1
    const random = Math.random();
    // Determinar o estado com base nas probabilidades
    let cumulativeProbability = 0;
    for (let i = 0; i < probabilities.length; i++) {
        cumulativeProbability += probabilities[i];
        if (random < cumulativeProbability) {
            return i;
        }
    }
}

